function showSampleInbox(){
  const current=(state.dmConversations||[]).filter(thread=>thread.demo);
  state.dmConversations=current.length?current:sampleDmConversations();
  if(!state.dmConversations.some(thread=>thread.id===state.activeDm))state.activeDm=state.dmConversations[0]?.id||'';
  state.dmUserId='sample-inbox';state.dmUnavailable=false;state.dmError='';state.dmLoading=false;state.dmReady=true;state.dmFolder='all';
  render();
}
function appendSampleDmMessage(thread,text,from='me'){
  const created_at=new Date().toISOString();
  thread.messages.push({id:`demo-${Date.now()}-${Math.random().toString(36).slice(2,7)}`,from,text,created_at,reactions:[]});
  thread.preview=text;thread.time=created_at;thread.unread=from!=='me';
}
async function initializeDm(){
  if(state.route!=='community'||state.communitySection!=='messages')return;
  if(user().demo){if(!state.dmReady||!state.dmConversations?.some(thread=>thread.demo))showSampleInbox();return;}
  if(dmInitPromise||state.dmLoading||state.dmReady)return;
  state.dmLoading=true;state.dmUnavailable=false;state.dmError='';
  render();
  dmInitPromise=(async()=>{
    const inbox=await loadInbox();
    if(state.route!=='community'||state.communitySection!=='messages'){state.dmLoading=false;return;}
    state.dmReady=true;state.dmUserId=inbox.user?.id||'';state.dmUnavailable=!inbox.user;state.dmConversations=inbox.conversations;
    if(!inbox.user){state.dmLoading=false;render();return;}
    if(!state.activeDm||!state.dmConversations.some(item=>item.id===state.activeDm))state.activeDm=state.dmConversations[0]?.id||'';
    watchInbox();
    await loadActiveDm();
  })().catch(error=>{const reason=String(error.message||'');state.dmUnavailable=/not configured|auth session missing|session missing|not authenticated/i.test(reason);state.dmError=state.dmUnavailable?'':reason||'Your private inbox is unavailable.';state.dmLoading=false;render();}).finally(()=>{dmInitPromise=null;});
}
async function loadActiveDm(){
  const thread=state.dmConversations?.find(item=>item.id===state.activeDm);
  if(!thread){state.dmLoading=false;stopConversation();render();return;}
  if(thread.demo){state.dmLoading=false;state.dmError='';render();const pane=$('#vc-dm-messages');if(pane)pane.scrollTop=pane.scrollHeight;return;}
  try{
    if(!thread.loaded){thread.messages=await loadMessages(thread.id,thread.searchJumpDate);thread.loaded=true;thread.searchJumpDate=null;}
    await watchConversation(thread.id);
    if(!thread.requestPending)await markRead(thread.id);
    thread.unread=false;thread.lastReadAt=new Date().toISOString();
    state.dmLoading=false;
    render();
    const pane=$('#vc-dm-messages');if(pane){const saved=state.dmScrollPositions?.[thread.id];pane.scrollTop=Number.isFinite(saved)?saved:pane.scrollHeight;}
  }catch(error){state.dmError=error.message||'Could not open this conversation.';state.dmLoading=false;render();}
}
async function refreshDmInbox(){if(user().demo){state.dmReady=false;showSampleInbox();return;}try{const inbox=await loadInbox();state.dmConversations=inbox.conversations;state.dmUserId=inbox.user?.id||'';render();}catch(error){toast(error.message||'Could not refresh messages');}}
