document.addEventListener('dm:message-change',async event=>{if(event.detail.conversationId!==state.activeDm)return;const pane=$('#vc-dm-messages'),wasNearBottom=pane?pane.scrollHeight-pane.scrollTop-pane.clientHeight<100:true,thread=state.dmConversations?.find(item=>item.id===state.activeDm);if(!thread)return;thread.messages=await loadMessages(thread.id).catch(()=>thread.messages);thread.loaded=true;render();const updated=$('#vc-dm-messages');if(updated&&wasNearBottom)updated.scrollTop=updated.scrollHeight;else if(updated){let badge=updated.querySelector('.vc-dm-new-message');if(!badge){badge=document.createElement('button');badge.className='vc-dm-new-message';badge.textContent='New message';badge.onclick=()=>{updated.scrollTop=updated.scrollHeight;badge.remove();};updated.append(badge);}}});
