document.addEventListener('dm:read-change',event=>{if(event.detail.conversationId!==state.activeDm)return;const change=event.detail.payload?.new;if(change&&change.user_id!==state.dmUserId){const thread=state.dmConversations?.find(item=>item.id===state.activeDm);if(thread){thread.peerReadAt=change.last_read_at;render();}}});
document.addEventListener('dm:optimistic-message',event=>{const thread=state.dmConversations?.find(item=>item.id===event.detail.conversationId);if(thread){thread.messages.push(event.detail.message);thread.preview=event.detail.message.text;render();const pane=$('#vc-dm-messages');if(pane)pane.scrollTop=pane.scrollHeight;}});
document.addEventListener('dm:message-sent',event=>{const thread=state.dmConversations?.find(item=>item.id===event.detail.conversationId);if(thread){thread.messages=thread.messages.filter(message=>message.id!==event.detail.pendingId&&message.id!==event.detail.message.id);thread.messages.push(event.detail.message);thread.preview=event.detail.message.text;render();}});
document.addEventListener('dm:send-failed',event=>{const thread=state.dmConversations?.find(item=>item.id===event.detail.conversationId);const message=thread?.messages.find(item=>item.id===event.detail.messageId);if(message){message.pending=false;message.failed=true;message.error=event.detail.error;render();}});
document.addEventListener('dm:error',event=>toast(event.detail.error||'Messaging update failed'));
document.addEventListener('dm:typing',event=>{const typing=event.detail.payload;if(!typing||typing.userId===state.dmUserId)return;state.dmTyping=Boolean(typing.isTyping);const status=$('.vc-dm-typing');if(status)status.hidden=!state.dmTyping;clearTimeout(window.__dmTypingExpiry);if(state.dmTyping)window.__dmTypingExpiry=setTimeout(()=>{state.dmTyping=false;const stale=$('.vc-dm-typing');if(stale)stale.hidden=true;},3500);});
document.addEventListener('scroll',async event=>{const pane=event.target;if(!pane.matches?.('#vc-dm-messages')||pane.scrollTop>12)return;const thread=state.dmConversations?.find(item=>item.id===state.activeDm);if(!thread||thread.loadingOlder||thread.hasOlder===false||thread.messages.length<50)return;thread.loadingOlder=true;const oldHeight=pane.scrollHeight,oldTop=pane.scrollTop;try{const older=await loadMessages(thread.id,thread.messages[0]?.created_at);const known=new Set(thread.messages.map(message=>message.id)),unique=older.filter(message=>!known.has(message.id));thread.hasOlder=older.length>=50&&unique.length>0;thread.messages=[...unique,...thread.messages];render();const updated=$('#vc-dm-messages');if(updated)updated.scrollTop=oldTop+(updated.scrollHeight-oldHeight);}catch(error){toast(error.message||'Could not load older messages');}finally{thread.loadingOlder=false;}},true);

