let soundContext;
function playUiSound(kind='tap'){
  if(state.uiSounds===false)return;
  try{const AudioContext=window.AudioContext||window.webkitAudioContext;if(!AudioContext)return;soundContext||=new AudioContext();const ctx=soundContext,tones={tap:[520,.035],nav:[430,.06],like:[660,.11],send:[740,.1],notify:[880,.14]};const [frequency,duration]=tones[kind]||tones.tap;const play=()=>{const osc=ctx.createOscillator(),gain=ctx.createGain();osc.type='sine';osc.frequency.setValueAtTime(frequency,ctx.currentTime);osc.frequency.exponentialRampToValueAtTime(frequency*.78,ctx.currentTime+duration);gain.gain.setValueAtTime(.0001,ctx.currentTime);gain.gain.exponentialRampToValueAtTime(.035,ctx.currentTime+.008);gain.gain.exponentialRampToValueAtTime(.0001,ctx.currentTime+duration);osc.connect(gain);gain.connect(ctx.destination);osc.start();osc.stop(ctx.currentTime+duration+.01);};if(ctx.state==='suspended')ctx.resume().then(play).catch(()=>{});else play();}catch{}
}

function seedSamplePostsToFyp(){
  const seedRevision=3+sampleExploreItems.length;
  if(state.sampleFypSeedVersion===seedRevision)return;
  const existing=new Set(state.posts.map(post=>post.id));
  sampleExploreItems.forEach(item=>{const post=state.posts.find(entry=>entry.id===`sample-${item.id}`);if(post?.sample){post.mediaUrl=sampleMediaUrl(item.media);post.mediaPoster=item.poster?samplePosterUrl(item.poster):'';post.mediaAlt=item.alt;post.type=item.kind==='video'?'reel':'post';post.tag=item.kind==='video'?'Video':'Experience';}});
  const additions=sampleExploreItems.filter(item=>!existing.has(`sample-${item.id}`)).map(item=>({
    id:`sample-${item.id}`,sample:true,author:'Vericove preview',ownerHandle:'vericove-preview',anonymous:false,
    time:'Sample post',community:item.category==='For You'?'Women’s Health':item.category,
    tag:item.kind==='video'?'Video':'Experience',type:item.kind==='video'?'reel':'post',
    title:item.title,
    body:`${item.caption} Sample media from this project: its creator, source and any health claims shown are not verified. This is not medical advice.`,
    mediaUrl:sampleMediaUrl(item.media),mediaPoster:item.poster?samplePosterUrl(item.poster):'',mediaAlt:item.alt,
    votes:0,voted:false,saved:false,comments:(sampleThreads[item.id]||[]).map((text,index)=>({author:`Sample reply ${index+1}`,text}))
  }));
  if(additions.length)state.posts=[...additions,...state.posts];
  state.sampleFypSeedVersion=seedRevision;persist();
}
seedSamplePostsToFyp();

let modalReturnFocus=null;
function dismissModal(){const root=$('#modal-root');delete root.dataset.reelComments;delete root.dataset.reelPostId;if(root.querySelector('.compose-sheet')&&selectedMedia?.url){URL.revokeObjectURL(selectedMedia.url);selectedMedia=null;}if(root.querySelector('.compose-sheet')&&selectedStory?.url){URL.revokeObjectURL(selectedStory.url);selectedStory=null;}closeModal(root,()=>{root.innerHTML='';document.body.classList.remove('modal-open');if(modalReturnFocus?.isConnected)modalReturnFocus.focus({preventScroll:true});modalReturnFocus=null;});}
function modal(title,body,actions='',variant=''){const root=$('#modal-root');if(!root.innerHTML.trim())modalReturnFocus=document.activeElement;document.body.classList.add('modal-open');root.innerHTML=`<section class="modal ${variant}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><header class="modal-head"><h2>${esc(title)}</h2><button class="modal-close" data-action="close-modal" aria-label="Close">×</button></header>${body}${actions?`<footer class="modal-actions">${actions}</footer>`:''}</section>`;root.onclick=event=>{if(event.target===root)dismissModal();};openModal(root,variant);const firstFocus=root.querySelector('.vc-explore-detail-close')||root.querySelector('input:not([type=hidden]),textarea,select,button');firstFocus?.focus({preventScroll:true});}
function commentMarkup(post){
  const comments=(post.comments||[]).map((comment,index)=>({...comment,id:comment.id||`${post.id}-comment-${index}`}));
  const renderNode=(comment,depth=0)=>{const liked=(state.commentLikes||[]).includes(comment.id),children=comments.filter(child=>child.parentId===comment.id);return `<article class="thread-comment" style="--reply-depth:${Math.min(depth,3)}"><span class="thread-avatar">${userAvatar({name:comment.author})}</span><div class="thread-comment-copy"><div class="thread-comment-head"><strong>${esc(comment.author)}</strong><time>${esc(comment.time||'5h')}</time></div><p>${esc(comment.text)}</p><div class="thread-comment-actions"><button type="button" class="reply-link" data-action="reply-to" data-post-id="${esc(post.id)}" data-comment-id="${esc(comment.id)}" data-author="${esc(comment.author)}">Reply</button><button type="button" class="thread-like ${liked?'is-liked':''}" data-action="like-comment" data-post-id="${esc(post.id)}" data-comment-id="${esc(comment.id)}" aria-label="${liked?'Unlike':'Like'} comment" aria-pressed="${liked}">${svg('heart',16)}</button></div>${children.length?`<div class="thread-comment-children">${children.map(child=>renderNode(child,depth+1)).join('')}</div>`:''}</div></article>`;};
  const roots=comments.filter(comment=>!comment.parentId||!comments.some(item=>item.id===comment.parentId));
  return `${roots.map(comment=>renderNode(comment)).join('')||'<p class="empty-thread">Be the first to respond thoughtfully.</p>'}<div class="reply-target" id="reply-target" hidden><span></span><button type="button" data-action="cancel-reply" aria-label="Cancel reply">×</button></div><form class="comment-form" data-post-id="${esc(post.id)}"><input type="hidden" name="parentId" value="" /><label class="sr-only" for="reply-content">Your reply</label><textarea id="reply-content" name="comment" rows="2" maxlength="600" placeholder="Add a thoughtful reply…" required></textarea><button class="btn primary" type="submit">Reply</button></form>`;
}
function openComments(post,reelCard=null){
  if(!post)return;
  modal('Comments',`<div class="discussion-context"><div class="post-community">${esc(post.community)} · ${esc(post.time)}</div><h3>${esc(post.title)}</h3><p>${esc(post.body)}</p></div><div class="thread-list" aria-label="Comments">${commentMarkup(post)}</div>`, '', 'comments-sheet');
  const root=$('#modal-root'),panel=root.querySelector('.comments-sheet');
  if(reelCard&&panel){const mediaRect=(reelCard.querySelector('.vc-reel-media')||reelCard).getBoundingClientRect();const width=Math.min(440,window.innerWidth-32),height=Math.min(820,window.innerHeight-32,Math.max(390,mediaRect.height));const left=Math.max(16,Math.min(mediaRect.right+72,window.innerWidth-width-16));const top=Math.max(16,Math.min(mediaRect.top+(mediaRect.height-height)/2,window.innerHeight-height-16));root.dataset.reelComments='true';root.dataset.reelPostId=String(post.id);panel.style.left=`${left}px`;panel.style.right='auto';panel.style.top=`${top}px`;panel.style.transform='none';panel.style.width=`${width}px`;panel.style.height=`${height}px`;}
}
