function toggleExploreComments(forceOpen){
  const detail=$('.explore-detail-sheet'),lightbox=detail?.querySelector('.vc-explore-lightbox'),panel=detail?.querySelector('.vc-explore-modal-comments');
  if(!detail||!lightbox||!panel)return;
  const open=forceOpen??!detail.classList.contains('has-comments');
  const mediaId=detail.querySelector('[data-action="like-explore-item"]')?.dataset.id,post=state.posts.find(entry=>entry.id===`sample-${mediaId}`),count=post?.comments?.length||0,countLabel=panel.querySelector('header strong span');
  if(countLabel)countLabel.textContent=String(count);
  clearTimeout(toggleExploreComments.hideTimer);
  if(open){panel.hidden=false;requestAnimationFrame(()=>{detail.classList.add('has-comments');lightbox.classList.add('has-comments');});}
  else{detail.classList.remove('has-comments');lightbox.classList.remove('has-comments');detail.querySelector('.vc-explore-post-actions [data-action="toggle-explore-comments"]')?.focus({preventScroll:true});toggleExploreComments.hideTimer=setTimeout(()=>{if(!detail.classList.contains('has-comments'))panel.hidden=true;},380);}
  detail.querySelectorAll('[data-action="toggle-explore-comments"]').forEach(control=>{control.setAttribute('aria-expanded',String(open));if(control.classList.contains('vc-explore-post-comments-link'))control.textContent=open?'Hide comments':`View all ${count} ${count===1?'comment':'comments'}`;});
}
