function refreshExploreSuggestions(raw=''){
  const panel=$('.vc-search-suggestions');if(!panel)return;
  const query=raw.trim().toLowerCase(),recent=state.exploreRecentSearches||[];
  const catalog=[...new Set([...recent,'Women’s health','PCOS','Mental Wellness','Nutrition','Fitness','Skincare','Research','Doctors','Communities','For You','wellness ideas','health stories',...sampleExploreItems.flatMap(item=>[item.title,item.category])])];
  const matches=query?catalog.filter(item=>item.toLowerCase().includes(query)):catalog.slice(0,8);
  const related=query?[`${raw.trim()} ideas`,`${raw.trim()} inspiration`,`${raw.trim()} videos`,`${raw.trim()} communities`]:[];
  const terms=[...new Set([...matches,...related])].slice(0,9);
  panel.innerHTML=`<span>${query?'SIMILAR SEARCHES':recent.length?'RECENT SEARCHES':'POPULAR SEARCHES'}</span>${terms.map(term=>`<button type="button" data-explore-suggest="${esc(term)}">${svg('search',14)}${esc(term)}<span>↗</span></button>`).join('')}`;
  panel.hidden=false;
}
