document.addEventListener('click',event=>{if(!event.target.closest('.vc-explore-search-wrap')){state.exploreSearchOpen=false;$('.vc-search-suggestions')?.setAttribute('hidden','');}});
window.addEventListener('popstate',()=>{
  const match=location.pathname.match(/^\/community(?:\/w\/([a-z0-9-]+)|\/(explore|reels|communities|messages|notifications|profile))?\/?$/i);
  if(!match)return;
  state.route='community';state.communitySection=match[1]?'communities':match[2]||'home';state.selectedCommunitySlug=match[1]||'';persist();render();
});

document.addEventListener('change',event=>{
  if(event.target.id==='post-photo'&&event.target.files?.length){
    const file=event.target.files[0];
    if((!file.type.startsWith('image/')&&!file.type.startsWith('video/'))||file.size>20*1024*1024){toast('Choose an image or video smaller than 20 MB');event.target.value='';return;}
    if(selectedMedia?.url)URL.revokeObjectURL(selectedMedia.url);
    selectedMedia={url:URL.createObjectURL(file),type:file.type.startsWith('video/')?'video':'image'};
    const preview=$('#media-preview');preview.innerHTML=selectedMedia.type==='video'?`<video src="${selectedMedia.url}" controls playsinline></video><button type="button" data-action="remove-photo">Remove video</button>`:`<img src="${selectedMedia.url}" alt="Selected photo preview" /><button type="button" data-action="remove-photo">Remove photo</button>`;preview.hidden=false;
    event.target.value='';return;
  }
  if(event.target.id==='story-media'&&event.target.files?.length){const file=event.target.files[0];if((!file.type.startsWith('image/')&&!file.type.startsWith('video/'))||file.size>20*1024*1024){toast('Choose a photo or video smaller than 20 MB');event.target.value='';return;}if(selectedStory?.url)URL.revokeObjectURL(selectedStory.url);selectedStory={url:URL.createObjectURL(file),type:file.type.startsWith('video/')?'video':'image'};const preview=$('#story-preview');preview.innerHTML=selectedStory.type==='video'?`<video src="${selectedStory.url}" controls playsinline></video>`:`<img src="${selectedStory.url}" alt="Story preview" />`;preview.hidden=false;event.target.value='';return;}
  if(event.target.id==='avatar-tray-file')return;
  if(event.target.type==='file'&&event.target.files?.length){const file=event.target.files[0];if(event.target.id==='record-file'){state.records.unshift({name:file.name.replace(/\.[^.]+$/,''),type:'Personal record',date:isoToday,file:file.name});persist();render();toast('Record added to this browser demo');}else toast('Upload is local-demo only.');event.target.value='';}
});
document.addEventListener('pointerdown',event=>{const button=event.target.closest('button');if(button)pressButton(button);});
document.addEventListener('pointerup',event=>{const button=event.target.closest('button');if(button)releaseButton(button);});
document.addEventListener('pointercancel',event=>{const button=event.target.closest('button');if(button)releaseButton(button);});
document.addEventListener('click',event=>{if(event.target.closest('.mobile-more, .vc-dock-more'))return;document.querySelectorAll('.mobile-more[open], .vc-dock-more[open]').forEach(menu=>menu.removeAttribute('open'));});
document.addEventListener('keydown',event=>{if(event.key==='Escape')document.querySelectorAll('.mobile-more[open], .vc-dock-more[open]').forEach(menu=>menu.removeAttribute('open'));});
document.addEventListener('pointerover',event=>{if(event.pointerType==='touch')return;const card=event.target.closest('.vc-discovery-card.is-video');if(!card||card.contains(event.relatedTarget))return;card.querySelector('[data-explore-video]')?.play().catch(()=>{});});
document.addEventListener('pointerout',event=>{const card=event.target.closest('.vc-discovery-card.is-video');if(!card||card.contains(event.relatedTarget))return;const video=card.querySelector('[data-explore-video]');if(video){video.pause();try{video.currentTime=0;}catch{}}});
document.addEventListener('keydown',event=>{const dialog=$('.explore-detail-sheet');if(event.key==='Tab'&&dialog){const controls=[...dialog.querySelectorAll('button:not([disabled]),a[href],input:not([disabled]),textarea:not([disabled]),select:not([disabled]),[tabindex]:not([tabindex="-1"])')].filter(control=>!control.closest('[hidden]')&&control.getClientRects().length);if(controls.length){const first=controls[0],last=controls[controls.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}return;}if(event.key!=='Escape')return;if(dialog?.classList.contains('has-comments')){toggleExploreComments(false);event.preventDefault();return;}dismissModal();});

